import java.util.*;
import java.io.*;

public class ar {

    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) throws Exception {
        FastReader fr = new FastReader();
        int n = fr.nextInt(), b = fr.nextInt();
        int[] array = new int[n];
        for (int i = 0; i < n; i++) array[i] = fr.nextInt();

        if ((n & 1) == 1) {
            System.out.print(0);
            return;
        }

        Map<Integer, Integer> differences = new HashMap<>();
        int evenCount = 0, oddCount = 0;
        for (int i = 0; i < n; i++) {
            if (array[i] % 2 == 0) evenCount++;
            else oddCount++;
            if (evenCount > 0 && oddCount > 0 && evenCount == oddCount && i + 1 < n) {
                differences.put(i, Math.abs(array[i] - array[i + 1]));
            }
        }

        if (differences.isEmpty()) {
            System.out.print(0);
        } else if (differences.size() == 1) {
            int val = new ArrayList<>(differences.values()).get(0);
            System.out.print(val <= b ? 1 : 0);
        } else {
            List<Integer> vals = new ArrayList<>(differences.values());
            Collections.sort(vals);
            int count = 0;
            for (int v : vals) {
                if (v <= b) {
                    b -= v;
                    count++;
                } else {
                    break;
                }
            }
            System.out.print(count);
        }
    }
}
